#!/usr/bin/env node
// Turns web/frame-twelve.html into a JS module the app can import.
//
// The HTML is the single source of truth and stays where it is; this only
// generates a derived file. Run it after editing the web app:
//
//   npm run bundle-html

const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, '..', '..', 'web', 'frame-twelve.html');
const OUT = path.join(__dirname, '..', 'src', 'frameTwelveHtml.js');

const html = fs.readFileSync(SRC, 'utf8');

// JSON.stringify handles every escaping case — backticks, quotes, newlines,
// and the backslashes inside the app's own regexes — which a template
// literal would not.
const body = `// GENERATED by scripts/bundle-html.js — do not edit.
// Source: web/frame-twelve.html (${html.length} bytes)
export default ${JSON.stringify(html)};
`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, body);

console.log(
  `bundled ${html.length} bytes -> ${path.relative(process.cwd(), OUT)}`
);
